// electron-builder afterPack hook.
//
// macOS: copies the precompiled Assets.car (built from icons/AppIcon.icon
// via `actool`, see icons/README.md) into the app bundle's Resources so
// macOS 26+ renders the native liquid-glass app icon. Older macOS falls
// back to icons/icon.icns (also generated by actool from the same .icon).
// The hook runs before code signing, so the added file gets sealed into
// the signature.
//
// It also refuses to produce an app without the native Keychain binding for
// its CPU: without it the Chrome cookie import can only fail.
const fs = require("fs");
const path = require("path");

/** electron-builder's `Arch` values for the CPUs a macOS app is built for. */
const KEYCHAIN_BINDING_ARCHS = { 1: ["x64"], 3: ["arm64"], 4: ["x64", "arm64"] };

/**
 * The Keychain bindings the packed app lacks. A binding is one prebuilt
 * `keyring.darwin-<cpu>.node`, wherever the packager placed it.
 *
 * @param {string} resourcesDir the app bundle's `Contents/Resources`
 * @param {number} arch electron-builder's `Arch` value for this pack
 * @returns {string[]} missing file names, empty when the app is complete
 */
function missingKeychainBindings(resourcesDir, arch) {
  const wanted = (KEYCHAIN_BINDING_ARCHS[arch] ?? []).map((cpu) => `keyring.darwin-${cpu}.node`);
  const found = new Set();
  const pending = [resourcesDir];
  while (pending.length > 0) {
    const directory = pending.pop();
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      if (entry.isDirectory()) pending.push(path.join(directory, entry.name));
      else found.add(entry.name);
    }
  }
  return wanted.filter((name) => !found.has(name));
}

async function afterPack(context) {
  if (context.electronPlatformName !== "darwin") return;
  const appName = context.packager.appInfo.productFilename;
  const resourcesDir = path.join(context.appOutDir, `${appName}.app`, "Contents", "Resources");
  const missing = missingKeychainBindings(resourcesDir, context.arch);
  if (missing.length > 0) {
    throw new Error(
      `The packed app has no ${missing.join(" or ")}. Install both macOS bindings first: ` +
        "pnpm install --frozen-lockfile --filter ./web --filter ./web/electron --cpu x64 --cpu arm64",
    );
  }
  fs.copyFileSync(
    path.join(__dirname, "..", "icons", "Assets.car"),
    path.join(resourcesDir, "Assets.car"),
  );
}

module.exports = afterPack;
module.exports.missingKeychainBindings = missingKeychainBindings;
